create table if not exists stations(id text primary key,name text not null,latitude double precision not null,longitude double precision not null,region text,status text default 'healthy',created_at timestamptz default now());
create table if not exists observations(id bigint generated always as identity primary key,station_id text references stations(id) on delete cascade,timestamp timestamptz not null,temperature double precision not null,pressure double precision not null,humidity double precision not null,created_at timestamptz default now());
create table if not exists anomalies(id text primary key,station_id text references stations(id) on delete cascade,observation_id bigint references observations(id) on delete set null,timestamp timestamptz not null,anomaly_type text not null,severity text not null,score double precision not null,confidence double precision not null,diagnosis text not null,reason text,fault_sensor text,recommended_action text,features jsonb,observed jsonb,expected jsonb,residuals jsonb,created_at timestamptz default now());
create table if not exists sensor_health(station_id text references stations(id) on delete cascade,timestamp timestamptz not null,temperature_health double precision,pressure_health double precision,humidity_health double precision,overall_health double precision,drift_score double precision,failure_probability double precision,primary key(station_id,timestamp));
create table if not exists alerts(id bigint generated always as identity primary key,anomaly_id text references anomalies(id) on delete cascade,channel text,status text default 'open',created_at timestamptz default now(),resolved_at timestamptz);
